package com.fooddelivery.delivery.entity; import jakarta.persistence.*;
@Entity @Table(name="delivery_items") public class DeliveryItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="order_id",nullable=false) private Long orderId; @Column(name="item_name",nullable=false,length=160) private String itemName; @Column(nullable=false) private Integer quantity; protected DeliveryItem(){} public DeliveryItem(Long o,String n,Integer q){orderId=o;itemName=n;quantity=q;} public Long getId(){return id;} public Long getOrderId(){return orderId;} public String getItemName(){return itemName;} public Integer getQuantity(){return quantity;} }
